"use client";

import { useEffect, useRef, useState } from "react";
import type { CSSProperties, HTMLAttributes } from "react";

/**
 * - `spin`: the whole orb turns on its vertical axis.
 * - `cascade`: the orb holds still while each row takes a full turn, one after another.
 * - `lift`: each ring pushes outward and settles back, one after another.
 * - `tide`: a narrow wave travels down the orb, pulling a few rows inward as it passes.
 * - `twist`: the orb scrambles itself like a twisty cube, a row or column turn at a time, then solves itself.
 * - `scan` (reading): a thin band of light reads down the orb at a steady pace.
 * - `rise` (uploading / downloading): a wave pushes rows outward on its way up and fades them off the top, or pulls them inward on its way down.
 * - `sweep` (searching): one lit column sweeps around the orb like a radar, with a short fading trail.
 * - `compact` (compacting): two inward waves leave the poles, meet at the equator as a thin waist, and let go.
 * - `swarm` (parallel tool calls): several narrow waves travel down the orb at once, evenly spaced.
 */
export type DotGlobeAnimation = "spin" | "cascade" | "lift" | "tide" | "twist" | "scan" | "rise" | "sweep" | "compact" | "swarm";

export type DotGlobePattern = "rings" | "fibonacci" | "grid";

export interface DotGlobeProps extends Omit<HTMLAttributes<HTMLDivElement>, "color"> {
  /** Which animation the orb runs. Changing it cross-fades from the old animation to the new one; every other prop keeps its value. */
  animation?: DotGlobeAnimation;
  /** How the dots are laid out on the sphere. Staggered and travelling animations follow it. */
  pattern?: DotGlobePattern;
  /** Diameter of the front-most dots in px. Back dots shrink automatically. */
  dotSize?: number;
  /** Number of rows / dot density. Higher = more dots. */
  density?: number;
  /** Canvas size in px (the orb is square). */
  size?: number;
  /**
   * Seconds for one turn (spin, twist, sweep), one row's turn (cascade), one ring's push (lift), one pole-to-pole sweep
   * (tide, scan, rise, swarm) or one squeeze (compact). Defaults to 1, or 0.5 for lift, 2 for scan and swarm, 2.4 for sweep and 1.8 for compact.
   */
  duration?: number;
  /** Seconds to rest between loops. twist: seconds the orb holds once scrambled, and again once solved. */
  gap?: number;
  /** cascade, lift: seconds between one row starting and the next one along. Defaults to 0.1, or 0.14 for lift. */
  stagger?: number;
  /** spin, cascade, sweep: which way it turns around the vertical axis. rise: "up" to upload (the default), "down" to download. */
  direction?: GlobeDirection;
  /** lift, tide: which end of the orb the wave starts from. */
  from?: "top" | "bottom";
  /** lift, rise, swarm: how far a ring pushes outward, as a fraction of the orb's radius. */
  lift?: number;
  /** tide, rise, compact, swarm: how far a wave pulls the dots in toward the vertical axis, as a fraction of the orb's radius. */
  depth?: number;
  /** tide, rise: how many rows the wave moves at once. */
  width?: number;
  /** swarm: waves travelling down the orb at once (1–4), one per call running in parallel. */
  waves?: number;
  /** twist: turns in each scramble. The same turns then play back in reverse to solve the orb. */
  moves?: number;
  /** Tilt toward the viewer in degrees, so the top of the orb shows. */
  tilt?: number;
  /** Dot color, any CSS color. */
  color?: string;
  /** Opacity of the dots furthest away (0–1). Front dots are always 1. */
  backOpacity?: number;
  /** Coast to a stop on the current frame. Turning it back off eases the animation back up to speed. */
  paused?: boolean;
  /** Accessible name; the wrapper is role="status". */
  label?: string;
}

type Motion = SpinSettings &
  CascadeSettings &
  LiftSettings &
  TideSettings &
  TwistSettings &
  ScanSettings &
  RiseSettings &
  SweepSettings &
  CompactSettings &
  SwarmSettings;

const ANIMATIONS: DotGlobeAnimation[] = ["spin", "cascade", "lift", "tide", "twist", "scan", "rise", "sweep", "compact", "swarm"];

/**
 * Used for any prop that isn't passed. The same for every animation, so switching animation changes nothing else.
 * rise reads the shared "left" as its default, "up".
 */
const DEFAULTS: Motion = { duration: 1, gap: 0.4, stagger: 0.1, direction: "left", from: "top", lift: 0.16, depth: 0.2, width: 3.5, moves: 4, waves: 2 };

/**
 * Where the shared default would break an animation: at 1s / 0.1s lift would push ~10 rings at once, not 3–4.
 * At 1s the scan and swarm bands and the sweep's head pass each row in ~0.1s, too fast to read, and the
 * compact waves race to the waist.
 */
const ANIMATION_DEFAULTS: Partial<Record<DotGlobeAnimation, Partial<Motion>>> = {
  lift: { duration: 0.5, stagger: 0.14 },
  scan: { duration: 2 },
  sweep: { duration: 2.4 },
  compact: { duration: 1.8 },
  swarm: { duration: 2 },
};

type Settings = GlobeSettings & Motion & { animation: DotGlobeAnimation };

/** Every number any of the animations reads, plus how much of each is on screen. */
function targetsOf(s: Settings) {
  return {
    ...globeTargets(s),
    ...spinMotion.targets(s),
    ...cascadeMotion.targets(s),
    ...liftMotion.targets(s),
    ...tideMotion.targets(s),
    ...twistMotion.targets(s),
    ...scanMotion.targets(s),
    ...riseMotion.targets(s),
    ...sweepMotion.targets(s),
    ...compactMotion.targets(s),
    ...swarmMotion.targets(s),
    ...mixTargets(ANIMATIONS, s.animation),
  };
}

function scene() {
  return mixScenes({
    spin: spinMotion.scene,
    cascade: cascadeMotion.scene,
    lift: liftMotion.scene,
    tide: tideMotion.scene,
    twist: twistMotion.scene,
    scan: scanMotion.scene,
    rise: riseMotion.scene,
    sweep: sweepMotion.scene,
    compact: compactMotion.scene,
    swarm: swarmMotion.scene,
  });
}

export function DotGlobe({
  animation = "spin",
  pattern = "rings",
  dotSize = 3,
  density = 12,
  size = 160,
  duration,
  gap,
  stagger,
  direction,
  from,
  lift,
  depth,
  width,
  moves,
  waves,
  tilt = 18,
  color = "#e4e4e7",
  backOpacity = 0.2,
  paused = false,
  label = "Thinking",
  ...rest
}: DotGlobeProps) {
  const active = ANIMATIONS.includes(animation) ? animation : "spin";
  const motion = withDefaults({ ...DEFAULTS, ...ANIMATION_DEFAULTS[active] }, { duration, gap, stagger, direction, from, lift, depth, width, moves, waves });
  const settings: Settings = { animation: active, pattern, dotSize, density, size, tilt, color, backOpacity, paused, ...motion };
  return <LoaderCanvas settings={settings} targets={targetsOf} shape={globeShape} settle={globeSettle} scene={scene} label={label} {...rest} />;
}

export default DotGlobe;

/**
 * Glide times are a spring's time constant, not a duration: a glide is about 90% of the way to its target
 * after twice its time, so `SETTLE` reads as a ~240ms change.
 */

/** Seconds (roughly) a changed prop takes to glide to its new value: size, spacing, timing and the like. */
const SETTLE = 0.12;

/** Color and opacity: faster, since nothing moves (~150ms). */
const FADE_SETTLE = 0.075;

/** Changing animation: one motion blending into the next (~300ms). */
const BLEND_SETTLE = 0.15;

/** Pausing: seconds (roughly) the animation takes to coast to a stop (~300ms). */
const STOP_SETTLE = 0.15;

/** Resuming: seconds (roughly) the animation takes to get back up to speed (~400ms). */
const START_SETTLE = 0.2;

/** A value that glides toward its target on a critically damped spring: no jump, no overshoot. */
type Glide = { value: number; velocity: number; target: number };

function glide(value: number): Glide {
  return { value, velocity: 0, target: value };
}

function snap(g: Glide) {
  g.value = g.target;
  g.velocity = 0;
}

/** Moves `g` toward its target. Returns false once it has arrived and is at rest. */
function stepGlide(g: Glide, dt: number, time: number) {
  if (g.value === g.target && g.velocity === 0) return false;
  const omega = 2 / time;
  const x = omega * dt;
  const decay = 1 / (1 + x + 0.48 * x * x + 0.235 * x * x * x);
  const change = g.value - g.target;
  const temp = (g.velocity + omega * change) * dt;
  g.velocity = (g.velocity - omega * temp) * decay;
  g.value = g.target + (change + temp) * decay;
  if (Math.abs(g.value - g.target) < 1e-3 && Math.abs(g.velocity) < 1e-3) snap(g);
  return true;
}

/** The glided value of every target, plus the canvas `size` and the pause `rate` (0 paused, 1 running). */
type Values<K extends string> = Record<K | "size" | "rate", number>;

/** What a scene sees each frame. `layers` holds every shape on screen; more than one while a change cross-fades. */
interface Frame<S, K extends string, L> {
  settings: S;
  v: Values<K>;
  layers: { shape: L; fade: number }[];
  size: number;
  /** The viewer asked for reduced motion: the clock holds still, so a scene that ends somewhere should jump there. */
  reduced: boolean;
}

interface Scene<S, K extends string, L> {
  /** Moves the scene's own clock on by `dt` seconds. Scale by `v.rate` so pausing coasts to a stop. */
  advance?(dt: number, frame: Frame<S, K, L>): void;
  /** Paints one frame onto a cleared canvas, already scaled to `size` px. */
  draw(ctx: CanvasRenderingContext2D, frame: Frame<S, K, L>): void;
}

interface LoaderCanvasProps<S extends { size: number; paused: boolean }, K extends string, L>
  extends Omit<HTMLAttributes<HTMLDivElement>, "color"> {
  /** The latest props. Read by `targets` and `shape` on every render, and by the scene every frame. */
  settings: S;
  /** Every number the scene reads, as the latest settings want it. Each glides to its new value. */
  targets: (s: NoInfer<S>) => Record<K, number>;
  /**
   * Geometry rebuilt when its key changes. The old shape's fade glides to 0 while the new one's glides to 1:
   * a plain cross-fade, unless `morph` links the two so the scene can move one into the other.
   */
  shape?: {
    key: (s: NoInfer<S>) => string;
    build: (s: NoInfer<S>) => L;
    /** Called when `to` replaces `from`, whose fade is `fade` at that moment. */
    morph?: (from: L, to: L, fade: number) => void;
    /** Seconds (roughly) a shape change takes. Defaults to `BLEND_SETTLE`. */
    settle?: number;
  };
  /** Seconds (roughly) each target takes to glide to a new value, by key. Unlisted keys take `SETTLE`. */
  settle?: Partial<Record<NoInfer<K> | "size", number>>;
  /** Seconds (roughly) pausing takes to coast to a stop, and resuming to get back up to speed. */
  pause?: { stop: number; start: number };
  /** Called once on mount; the returned scene keeps its own clock between frames. */
  scene: () => Scene<NoInfer<S>, K, L>;
  label: string;
}

/**
 * A square canvas that runs a scene: props glide instead of jumping, pausing coasts, shape changes
 * cross-fade or morph, reduced motion holds still, and the loop sleeps once nothing is moving.
 */
function LoaderCanvas<S extends { size: number; paused: boolean }, K extends string, L>({
  settings,
  targets,
  shape,
  settle,
  pause,
  scene,
  label,
  className,
  style,
  ...rest
}: LoaderCanvasProps<S, K, L>) {
  const wrapperRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  // Only the first size reaches the DOM through React; after that the loop glides it.
  const [initialSize] = useState(settings.size);
  const latest = useRef({ settings, targets, shape, settle, pause, scene });
  const wakeRef = useRef<(() => void) | null>(null);

  useEffect(() => {
    latest.current = { settings, targets, shape, settle, pause, scene };
    wakeRef.current?.();
  });

  useEffect(() => {
    const wrapper = wrapperRef.current;
    const canvas = canvasRef.current;
    const ctx = canvas?.getContext("2d");
    if (!wrapper || !canvas || !ctx) return;

    const dpr = Math.min(window.devicePixelRatio || 1, 3);
    const reduceMotion = window.matchMedia("(prefers-reduced-motion: reduce)");
    const { settings: first, shape: shapeOf, scene: makeScene } = latest.current;
    const sceneNow = makeScene();
    const glides = {} as Record<string, Glide>;
    const v = {} as Values<K>;
    let shapes = shapeOf ? [{ key: shapeOf.key(first), shape: shapeOf.build(first), fade: glide(1) }] : [];
    const frameInfo: Frame<S, K, L> = { settings: first, v, layers: [], size: 1, reduced: reduceMotion.matches };
    let shownSize = -1;
    let frame = 0;
    let last = 0;

    const targetsNow = () => {
      const { settings: s, targets } = latest.current;
      return { ...targets(s), size: s.size, rate: s.paused ? 0 : 1 } as Record<string, number>;
    };
    for (const [k, value] of Object.entries(targetsNow())) glides[k] = glide(value);

    /** Refreshes what the scene reads from the glides and shapes. */
    const read = () => {
      for (const k in glides) (v as Record<string, number>)[k] = glides[k].value;
      frameInfo.settings = latest.current.settings;
      frameInfo.layers = shapes.map(({ shape, fade }) => ({ shape, fade: fade.value }));
      frameInfo.size = Math.max(1, v.size);
      frameInfo.reduced = reduceMotion.matches;
    };

    const sync = () => {
      const { settings: s, shape: shapeOf } = latest.current;
      for (const [k, value] of Object.entries(targetsNow())) glides[k].target = value;
      if (shapeOf) {
        const key = shapeOf.key(s);
        if (key !== shapes[shapes.length - 1].key) {
          for (const shape of shapes) shape.fade.target = 0;
          const fade = glide(0);
          fade.target = 1;
          const prev = shapes[shapes.length - 1];
          const next = { key, shape: shapeOf.build(s), fade };
          shapeOf.morph?.(prev.shape, next.shape, prev.fade.value);
          shapes.push(next);
        }
      }
      // Reduced motion: hold still and apply changes at once.
      if (reduceMotion.matches) {
        glides.rate.target = 0;
        for (const g of Object.values(glides)) snap(g);
        for (const shape of shapes) snap(shape.fade);
      }
    };

    const draw = () => {
      read();
      const size = frameInfo.size;
      if (size !== shownSize) {
        shownSize = size;
        wrapper.style.width = wrapper.style.height = `${size}px`;
        canvas.style.width = canvas.style.height = `${size}px`;
        const px = Math.round(size * dpr);
        if (canvas.width !== px) canvas.width = canvas.height = px;
      }
      ctx.setTransform(canvas.width / size, 0, 0, canvas.width / size, 0, 0);
      ctx.clearRect(0, 0, size, size);
      sceneNow.draw(ctx, frameInfo);
      ctx.globalAlpha = 1;
    };

    const tick = (now: number) => {
      const dt = last ? Math.min(0.1, (now - last) / 1000) : 0;
      last = now;
      let moving = false;
      const times: Partial<Record<string, number>> = latest.current.settle ?? {};
      const pauseTimes = latest.current.pause;
      for (const [k, g] of Object.entries(glides)) {
        // Stopping and starting take their own times; every other target its own, else `SETTLE`.
        const time =
          k === "rate"
            ? g.target > 0
              ? (pauseTimes?.start ?? START_SETTLE)
              : (pauseTimes?.stop ?? STOP_SETTLE)
            : (times[k] ?? SETTLE);
        if (stepGlide(g, dt, time)) moving = true;
      }
      const shapeSettle = latest.current.shape?.settle ?? BLEND_SETTLE;
      for (const shape of shapes) if (stepGlide(shape.fade, dt, shapeSettle)) moving = true;
      shapes = shapes.filter((shape) => shape.fade.target > 0 || shape.fade.value > 0);

      if (sceneNow.advance) {
        read();
        sceneNow.advance(dt, frameInfo);
      }
      draw();
      // Sleep once everything has settled and the animation is paused.
      frame = moving || glides.rate.value > 0 ? requestAnimationFrame(tick) : 0;
    };

    const wake = () => {
      sync();
      if (frame) return;
      last = 0;
      frame = requestAnimationFrame(tick);
    };

    wakeRef.current = wake;
    reduceMotion.addEventListener("change", wake);
    sync();
    draw();
    wake();
    return () => {
      cancelAnimationFrame(frame);
      wakeRef.current = null;
      reduceMotion.removeEventListener("change", wake);
    };
  }, []);

  const wrapperStyle: CSSProperties = { width: initialSize, height: initialSize, ...style };

  return (
    <div ref={wrapperRef} role="status" aria-label={label} className={className} style={wrapperStyle} {...rest}>
      <canvas ref={canvasRef} style={{ width: initialSize, height: initialSize, display: "block" }} />
    </div>
  );
}

let probe: CanvasRenderingContext2D | null = null;

/** Resolves any CSS color to sRGB [r, g, b, a] by painting it into one pixel, so it can be blended. */
function parseColor(color: string): [number, number, number, number] {
  probe ??= document.createElement("canvas").getContext("2d", { willReadFrequently: true });
  if (!probe) return [228, 228, 231, 1];
  probe.clearRect(0, 0, 1, 1);
  probe.fillStyle = "#000"; // An invalid color leaves fillStyle as it was, so start from a known one.
  probe.fillStyle = color;
  probe.fillRect(0, 0, 1, 1);
  const [r, g, b, a] = probe.getImageData(0, 0, 1, 1).data;
  return [r, g, b, a / 255];
}

/** A CSS color as glide targets, so a color change blends instead of jumping. */
function colorTargets(color: string) {
  const [red, green, blue, alpha] = parseColor(color);
  return { red, green, blue, alpha };
}

/** The blended color as an opaque CSS color; its alpha is applied per dot through globalAlpha. */
function rgb(v: { red: number; green: number; blue: number }) {
  return `rgb(${v.red} ${v.green} ${v.blue})`;
}

/** How the dots are laid out on the sphere. */
type GlobePattern = "rings" | "fibonacci" | "grid";

/** Props every dot sphere takes. */
interface GlobeSettings {
  pattern: GlobePattern;
  dotSize: number;
  density: number;
  size: number;
  tilt: number;
  color: string;
  backOpacity: number;
  paused: boolean;
}

/**
 * A point on the unit sphere. `row` is its latitude row from the top (0 to `rows`); `step` is its
 * place in the pattern's own order, which on the spiral winds down the arms instead of the rows.
 */
type GlobePoint = { x: number; y: number; z: number; row: number; step: number };

/** Where `place` puts a point before the tilt, plus how much it shrinks (`size`) and dims (`dim`). */
type Placed = { x: number; y: number; z: number; size: number; dim: number };

/** Back dots are drawn at this fraction of `dotSize`. */
const BACK_SCALE = 0.35;

/** Rows the spiral stripe drops over one full turn around the orb, as a fraction of all rows. */
const SPIRAL_PITCH = 0.5;

function rowsOf(s: GlobeSettings) {
  return Math.max(3, Math.round(s.density));
}

function buildPoints(pattern: GlobePattern, rows: number) {
  const points: GlobePoint[] = [];

  if (pattern === "fibonacci") {
    // The spiral has no rows, so band dots by height into rows, and let the step follow its arms:
    // mixing height with how far around the orb a dot sits turns a wave into a diagonal stripe
    // winding down the sphere. The stripe's seam (where "around" wraps) sits at the back, where the dots are faintest.
    const count = Math.round(rows * rows * 1.25);
    const golden = Math.PI * (3 - Math.sqrt(5));
    const pitch = rows * SPIRAL_PITCH;
    for (let i = 0; i < count; i++) {
      const y = 1 - ((i + 0.5) / count) * 2;
      const r = Math.sqrt(1 - y * y);
      const a = i * golden;
      const x = Math.cos(a) * r;
      const z = Math.sin(a) * r;
      const around = Math.atan2(-x, z) / (Math.PI * 2) + 0.5;
      points.push({ x, y, z, row: Math.round(((1 - y) / 2) * rows), step: ((1 - y) / 2) * rows + around * pitch });
    }
    return { points, steps: rows + pitch };
  }

  // Rings and grid share latitude rows; each row moves as one, so its step is its row number.
  // Poles get a single dot each.
  points.push({ x: 0, y: 1, z: 0, row: 0, step: 0 }, { x: 0, y: -1, z: 0, row: rows, step: rows });
  const cols = rows * 2;
  for (let i = 1; i < rows; i++) {
    const lat = Math.PI / 2 - (i / rows) * Math.PI;
    const y = Math.sin(lat);
    const r = Math.cos(lat);
    // Rings keep even spacing along each row; grid keeps meridians aligned.
    const n = pattern === "grid" ? cols : Math.max(1, Math.round(cols * r));
    const offset = pattern === "grid" ? 0 : (i % 2) * (Math.PI / n);
    for (let j = 0; j < n; j++) {
      const a = (j / n) * Math.PI * 2 + offset;
      points.push({ x: Math.cos(a) * r, y, z: Math.sin(a) * r, row: i, step: i });
    }
  }
  return { points, steps: rows };
}

/** The sphere's points, plus scratch space for projecting and depth-sorting them each frame. */
interface GlobeShape {
  pattern: GlobePattern;
  points: GlobePoint[];
  rows: number;
  /** The last step on the orb, so a sweep from step 0 to `steps` crosses all of it. */
  steps: number;
  placed: Placed[];
  order: number[];
  // Each row's own spin angle, for animations that turn rows separately. Accumulated so
  // timing changes mid-turn bend the motion instead of jumping it.
  rowAngles: Float64Array;
  rowSin: Float64Array;
  rowCos: Float64Array;
  /** This orb's fade as of the last frame: 0 to 1 while it morphs in, 1 to 0 while it morphs out. */
  fade: number;
  /** Set while this orb morphs in: each point sets off from `from`'s point `source[i]`. */
  arrival: { from: GlobeShape; source: Int32Array; frozen: number | null } | null;
  /**
   * Set while this orb morphs out. Points some new point set off from (`kept`) hand over to it at once;
   * the rest travel into `to`'s point `target[i]` and fade on the way.
   */
  leaving: { to: GlobeShape; target: Int32Array; kept: Uint8Array; start: number } | null;
}

function buildGlobe(s: GlobeSettings): GlobeShape {
  const rows = rowsOf(s);
  const { points, steps } = buildPoints(s.pattern, rows);
  return {
    pattern: s.pattern,
    points,
    rows,
    steps,
    placed: points.map((): Placed => ({ x: 0, y: 0, z: 0, size: 1, dim: 1 })),
    order: points.map((_, i) => i),
    rowAngles: new Float64Array(rows + 1),
    rowSin: new Float64Array(rows + 1),
    rowCos: new Float64Array(rows + 1).fill(1),
    fade: 1,
    arrival: null,
    leaving: null,
  };
}

/** For each point in `to`, the closest point in `from` on the sphere. */
function nearest(from: GlobePoint[], to: GlobePoint[]) {
  const out = new Int32Array(to.length);
  for (let i = 0; i < to.length; i++) {
    const p = to[i];
    let best = -Infinity;
    for (let j = 0; j < from.length; j++) {
      const q = from[j];
      const dot = p.x * q.x + p.y * q.y + p.z * q.z;
      if (dot > best) {
        best = dot;
        out[i] = j;
      }
    }
  }
  return out;
}

/**
 * Links an orb to the one replacing it, so the same dots travel into the new layout instead of
 * the two cross-fading. Every new dot sets off from its closest old dot; old dots no new one picked
 * glide into their closest new dot and fade out there.
 */
function morphGlobe(from: GlobeShape, to: GlobeShape, fade: number) {
  // A change mid-morph: hold the old orb where it got to, and set off from there.
  if (from.arrival) {
    if (fade < 1) from.arrival.frozen = fade;
    else from.arrival = null;
  }
  const source = nearest(from.points, to.points);
  const kept = new Uint8Array(from.points.length);
  for (const j of source) kept[j] = 1;
  to.arrival = { from, source, frozen: null };
  from.leaving = { to, target: nearest(to.points, from.points), kept, start: Math.max(1e-3, fade) };
}

/** Identifies an orb's geometry; a pattern or density change morphs the old orb's dots into the new one. */
function globeKey(s: GlobeSettings) {
  return `${s.pattern}:${rowsOf(s)}`;
}

/**
 * Dots only travel to their nearest spot in the new layout, a short way, so a pattern or density change
 * takes the same ~300ms as switching animation: every structural change in the row blends at one pace.
 */
const globeShape = { key: globeKey, build: buildGlobe, morph: morphGlobe, settle: BLEND_SETTLE };

/** The globe's own glide targets; spread these into a component's targets. */
function globeTargets(s: GlobeSettings) {
  return { ...colorTargets(s.color), dotSize: s.dotSize, tilt: s.tilt, backOpacity: s.backOpacity };
}

type GlobeKey = keyof ReturnType<typeof globeTargets>;

function lerpPlaced(a: Placed, b: Placed, t: number) {
  b.x = a.x + (b.x - a.x) * t;
  b.y = a.y + (b.y - a.y) * t;
  b.z = a.z + (b.z - a.z) * t;
  b.size = a.size + (b.size - a.size) * t;
  b.dim = a.dim + (b.dim - a.dim) * t;
}

/**
 * Places, tilts, depth-sorts and paints every orb on screen. `placeFor` is called once per orb and
 * returns how to place each of its points; far dots shrink and fade, so only placement varies.
 * While a pattern changes, dots are placed partway between the old orb's motion and the new one's.
 */
function drawGlobe<S, K extends string, L extends GlobeShape>(
  ctx: CanvasRenderingContext2D,
  { v, layers, size }: Frame<S, K | GlobeKey, L>,
  radius: number,
  placeFor: (shape: L) => (point: GlobePoint, out: Placed) => void,
) {
  const dotSize = Math.max(0, v.dotSize);
  const backOpacity = v.backOpacity;
  const center = size / 2;
  const tiltRad = (v.tilt * Math.PI) / 180;
  const sinT = Math.sin(tiltRad);
  const cosT = Math.cos(tiltRad);

  const placers = new Map<L, (point: GlobePoint, out: Placed) => void>();
  const placerOf = (shape: L) => {
    let place = placers.get(shape);
    if (!place) placers.set(shape, (place = placeFor(shape)));
    return place;
  };
  const scratch: Placed[] = [];
  const toward: Placed = { x: 0, y: 0, z: 0, size: 1, dim: 1 };

  /** Where point `i` shows: its own motion, or partway there from the orb it is morphing in from. */
  const placeAt = (shape: L, i: number, out: Placed, depth = 0) => {
    out.size = out.dim = 1;
    placerOf(shape)(shape.points[i], out);
    const arrival = shape.arrival;
    if (!arrival) return;
    const t = arrival.frozen ?? shape.fade;
    if (t >= 1) return;
    const start = (scratch[depth] ??= { x: 0, y: 0, z: 0, size: 1, dim: 1 });
    placeAt(arrival.from as L, arrival.source[i], start, depth + 1);
    lerpPlaced(start, out, t);
  };

  for (const layer of layers) {
    const { shape } = layer;
    shape.fade = layer.fade;
    // Arrived: let go of the old orb.
    if (shape.arrival && !shape.leaving && shape.fade >= 1) shape.arrival = null;
  }

  ctx.fillStyle = rgb(v);
  for (const { shape, fade } of layers) {
    const { points, placed, order, leaving } = shape;
    // 1 while a leaving orb's unpicked dots are still fully on, down to 0 as they arrive.
    const keep = leaving ? Math.min(1, Math.max(0, fade / leaving.start)) : 1;
    for (let i = 0; i < points.length; i++) {
      const p = placed[i];
      placeAt(shape, i, p);
      if (leaving) {
        if (leaving.kept[i]) p.dim = 0;
        else {
          placeAt(leaving.to as L, leaving.target[i], toward);
          lerpPlaced(p, toward, 1 - keep);
          Object.assign(p, toward);
          p.dim *= keep;
        }
      }
      // Tilt toward the viewer, so the top of the orb shows.
      const { y, z } = p;
      p.y = y * cosT - z * sinT;
      p.z = y * sinT + z * cosT;
    }
    order.sort((i, j) => placed[i].z - placed[j].z);

    const alpha = v.alpha;
    for (const i of order) {
      const p = placed[i];
      if (p.dim <= 0) continue;
      const depth = Math.min(1, Math.max(0, (p.z + 1) / 2)); // 0 = back, 1 = front
      const r = (dotSize / 2) * (BACK_SCALE + (1 - BACK_SCALE) * depth) * p.size;
      ctx.globalAlpha = alpha * (backOpacity + (1 - backOpacity) * depth) * p.dim;
      ctx.beginPath();
      ctx.arc(center + p.x * radius, center - p.y * radius, r, 0, Math.PI * 2);
      ctx.fill();
    }
  }
}

function easeInOutCubic(t: number) {
  return t < 0.5 ? 4 * t * t * t : 1 - (-2 * t + 2) ** 3 / 2;
}

/** A CSS `cubic-bezier(x1, y1, x2, y2)` as a function of progress 0..1. */
function cubicBezier(x1: number, y1: number, x2: number, y2: number) {
  const ax = 3 * x1 - 3 * x2 + 1;
  const bx = 3 * x2 - 6 * x1;
  const cx = 3 * x1;
  const ay = 3 * y1 - 3 * y2 + 1;
  const by = 3 * y2 - 6 * y1;
  const cy = 3 * y1;
  const curveX = (s: number) => ((ax * s + bx) * s + cx) * s;
  const curveY = (s: number) => ((ay * s + by) * s + cy) * s;
  const slopeX = (s: number) => (3 * ax * s + 2 * bx) * s + cx;
  return (t: number) => {
    if (t <= 0) return 0;
    if (t >= 1) return 1;
    // Newton's method finds the curve parameter whose x is `t`; bisection catches the flat spots.
    let s = t;
    for (let i = 0; i < 6; i++) {
      const dx = curveX(s) - t;
      const slope = slopeX(s);
      if (Math.abs(dx) < 1e-6) return curveY(s);
      if (Math.abs(slope) < 1e-6) break;
      s -= dx / slope;
    }
    let lo = 0;
    let hi = 1;
    s = t;
    for (let i = 0; i < 20; i++) {
      const x = curveX(s);
      if (Math.abs(x - t) < 1e-6) break;
      if (x < t) lo = s;
      else hi = s;
      s = (lo + hi) / 2;
    }
    return curveY(s);
  };
}

/** Strong ease-out, `cubic-bezier(0.23, 1, 0.32, 1)`: for things arriving or leaving. */
const easeOut = cubicBezier(0.23, 1, 0.32, 1);

/** Strong ease-in-out, `cubic-bezier(0.77, 0, 0.175, 1)`: for things moving or morphing on screen. */
const easeInOut = cubicBezier(0.77, 0, 0.175, 1);

/**
 * Every way a dot sphere can move. Each motion turns its props into glide targets and runs a scene
 * over the shared globe geometry, so single loaders and the switchable DotGlobe draw the same thing.
 */

type GlobeFrame<K extends string> = Frame<unknown, K | GlobeKey, GlobeShape>;

/**
 * The orb's radius, the same for every motion. Where lift is in play (DotLift, or DotGlobe whatever
 * animation it runs), it leaves room for a ring at the peak of its push, so switching animation never resizes the orb.
 */
function radiusOf({ v, size }: GlobeFrame<never>) {
  const lift = Math.max(0, (v as Partial<Record<"lift", number>>).lift ?? 0);
  return (size / 2 - Math.max(0, v.dotSize)) / (1 + lift);
}

/** Gap (s) at which a spin turn is fully eased; smaller gaps blend toward a linear spin, 0 being linear. */
const SPIN_EASE_GAP = 0.2;

/** Seconds (roughly) a resting row takes to settle back square after a timing change knocked it off. */
const CASCADE_REALIGN = 0.12;

/** Opacity a dot keeps at the deepest point of the tide, so sunken dots read as further inside. */
const TIDE_SUNK_OPACITY = 0.55;

/**
 * Seconds (roughly) each target glides for when its prop changes, shared by DotGlobe and every single
 * sphere; unlisted keys (size, dot size, tilt, lift, depth, width, timing) take `SETTLE`. Color and opacity
 * fade faster, since nothing moves. Direction flips and animation switches blend one motion into the next.
 */
const globeSettle = {
  red: FADE_SETTLE,
  green: FADE_SETTLE,
  blue: FADE_SETTLE,
  alpha: FADE_SETTLE,
  backOpacity: FADE_SETTLE,
  dir: BLEND_SETTLE,
  from: BLEND_SETTLE,
  mix_spin: BLEND_SETTLE,
  mix_cascade: BLEND_SETTLE,
  mix_lift: BLEND_SETTLE,
  mix_tide: BLEND_SETTLE,
  mix_twist: BLEND_SETTLE,
  mix_scan: BLEND_SETTLE,
  mix_rise: BLEND_SETTLE,
  mix_sweep: BLEND_SETTLE,
  mix_compact: BLEND_SETTLE,
  mix_swarm: BLEND_SETTLE,
  down: BLEND_SETTLE,
};

/**
 * Which way a motion runs: left / right around the vertical axis (spin, cascade, sweep), or up / down (rise).
 * One type so DotGlobe can share a single `direction` prop; each motion reads the values it knows and
 * treats the rest as its default.
 */
type GlobeDirection = "left" | "right" | "up" | "down";

/** A loop of one move (`at` runs 0 to 1), then a rest (`rested` seconds), over and over. */
type MoveLoop = { at: number; rested: number };

/**
 * Runs `seconds` through a move-then-rest loop. Progress is kept rather than worked out from a cycle,
 * so changing the timing only changes the speed: a longer gap never jumps a move under way.
 * `moved` hears each stretch of progress, so a spin can add the turns up.
 */
function runMoveLoop(loop: MoveLoop, seconds: number, length: number, gap: number, moved?: (from: number, to: number) => void) {
  // A frame can hold several short moves (a zero gap takes none at all); cap it so nothing spins.
  for (let guard = 0; guard < 16 && seconds > 0; guard++) {
    if (loop.at < 1) {
      const from = loop.at;
      const need = (1 - from) * length;
      loop.at = seconds < need ? from + seconds / length : 1;
      seconds -= Math.min(seconds, need);
      moved?.(from, loop.at);
    } else {
      const need = Math.max(0, gap - loop.rested);
      if (seconds < need) {
        loop.rested += seconds;
        seconds = 0;
      } else {
        seconds -= need;
        loop.at = loop.rested = 0;
      }
    }
  }
}

interface SpinSettings {
  duration: number;
  gap: number;
  direction: GlobeDirection;
}

/** The whole orb spins on its vertical axis. */
const spinMotion = {
  targets(s: SpinSettings) {
    return {
      duration: s.duration,
      gap: s.gap,
      // Spin velocity sign; flipping it slows the orb, stops it, and spins it back up the other way.
      dir: s.direction === "right" ? -1 : 1,
    };
  },
  scene(): Scene<unknown, "duration" | "gap" | "dir" | GlobeKey, GlobeShape> {
    // One turn, then a rest for `gap`; advanced by rate so pausing coasts to a stop.
    const loop: MoveLoop = { at: 0, rested: 0 };
    let angle = 0;

    return {
      advance(dt, { v }) {
        const gap = Math.max(0, v.gap);
        // With no gap the spin is linear so consecutive turns join seamlessly; a gap eases each turn in and out.
        // easeInOutCubic, not the stronger easeInOut: a whole turn at its peak already sweeps more than a dot
        // spacing a frame, and a faster middle strobes the lattice.
        const ease = Math.min(1, gap / SPIN_EASE_GAP);
        const turned = (x: number) => x + (easeInOutCubic(x) - x) * ease;
        runMoveLoop(loop, dt * v.rate, Math.max(0.05, v.duration), gap, (from, to) => {
          angle = (angle + (turned(to) - turned(from)) * Math.PI * 2 * v.dir) % (Math.PI * 2);
        });
      },
      draw(ctx, frame) {
        const sinA = Math.sin(angle);
        const cosA = Math.cos(angle);
        drawGlobe(ctx, frame, radiusOf(frame), () => ({ x, y, z }, out) => {
          // Spin around the vertical axis.
          out.x = x * cosA + z * sinA;
          out.y = y;
          out.z = -x * sinA + z * cosA;
        });
      },
    };
  },
};

interface CascadeSettings {
  duration: number;
  stagger: number;
  gap: number;
  direction: GlobeDirection;
}

/** The orb holds still while each row takes a full turn, one after another from the top. */
const cascadeMotion = {
  targets(s: CascadeSettings) {
    return {
      duration: s.duration,
      stagger: s.stagger,
      gap: s.gap,
      // Spin velocity sign; flipping it slows turning rows, stops them, and turns them back the other way.
      dir: s.direction === "right" ? -1 : 1,
    };
  },
  scene(): Scene<unknown, "duration" | "stagger" | "gap" | "dir" | GlobeKey, GlobeShape> {
    // Seconds into the current wave, advanced by rate so pausing coasts to a stop. Kept in seconds, not as
    // a fraction of the cycle, so a gap change never shifts the rows mid-turn.
    let now = 0;

    return {
      advance(dt, { v, layers: onScreen }) {
        const shapes = onScreen.map((layer) => layer.shape);
        const turn = Math.max(0.05, v.duration);
        const stagger = Math.max(0, v.stagger);
        // Sized for the tallest orb on screen, so a fading-out orb's rows still finish their turn.
        const cycle = Math.max(...shapes.map((shape) => shape.rows)) * stagger + turn + Math.max(0, v.gap);
        const settle = 1 - Math.exp(-dt / CASCADE_REALIGN);
        const from = now;
        const to = now + dt * v.rate;

        // Each row runs one eased 360° turn, starting `stagger` seconds after the row above. easeInOutCubic,
        // not the stronger easeInOut, for the same reason as spin: a faster middle strobes the turning row.
        const progress = (time: number, l: number) => {
          const whole = Math.floor(time / cycle);
          return whole + Math.min(1, Math.max(0, (time - whole * cycle - l * stagger) / turn));
        };
        const turnsAt = (time: number, l: number) => {
          const x = progress(time, l);
          const whole = Math.floor(x);
          return whole + easeInOutCubic(x - whole);
        };

        for (const shape of shapes) {
          for (let l = 0; l <= shape.rows; l++) {
            let a = shape.rowAngles[l] + (turnsAt(to, l) - turnsAt(from, l)) * Math.PI * 2 * v.dir;
            a %= Math.PI * 2;
            const x = progress(to, l) % 1;
            // A row at rest belongs square to the orb; ease it back if a timing change left it skewed.
            if (x === 0) a -= (a - Math.PI * 2 * Math.round(a / (Math.PI * 2))) * settle;
            shape.rowAngles[l] = a;
            shape.rowSin[l] = Math.sin(a);
            shape.rowCos[l] = Math.cos(a);
          }
        }
        now = to % cycle;
      },
      draw(ctx, frame) {
        drawGlobe(ctx, frame, radiusOf(frame), ({ rowSin, rowCos }) => ({ x, y, z, row }, out) => {
          const sinA = rowSin[row];
          const cosA = rowCos[row];
          // Spin the row around the vertical axis.
          out.x = x * cosA + z * sinA;
          out.y = y;
          out.z = -x * sinA + z * cosA;
        });
      },
    };
  },
};

interface LiftSettings {
  lift: number;
  duration: number;
  stagger: number;
  gap: number;
  from: "top" | "bottom";
}

/** The orb holds still while each ring pushes outward and settles back, one after another. */
const liftMotion = {
  targets(s: LiftSettings) {
    return {
      lift: s.lift,
      duration: s.duration,
      stagger: s.stagger,
      gap: s.gap,
      // 0 runs the wave top to bottom, 1 bottom to top; gliding between them re-routes it smoothly.
      from: s.from === "bottom" ? 1 : 0,
    };
  },
  scene(): Scene<unknown, "lift" | "duration" | "stagger" | "gap" | "from" | GlobeKey, GlobeShape> {
    type F = GlobeFrame<"lift" | "duration" | "stagger" | "gap" | "from">;
    // Seconds into the current wave, advanced by rate so pausing coasts to a stop. Kept in seconds, not as
    // a fraction of the cycle, so a gap change never moves the rings mid-push.
    let now = 0;

    /** Seconds from the first ring leaving to the last one setting off, sized for the tallest orb on screen. */
    const spanOf = ({ v, layers }: F) => Math.max(...layers.map((layer) => layer.shape.steps)) * Math.max(0, v.stagger);
    const cycleOf = (frame: F) => spanOf(frame) + Math.max(0.05, frame.v.duration) + Math.max(0, frame.v.gap);

    return {
      advance(dt, frame) {
        now = (now + dt * frame.v.rate) % cycleOf(frame);
      },
      draw(ctx, frame) {
        const { v } = frame;
        const lift = Math.max(0, v.lift);
        const fromBottom = v.from;
        const turn = Math.max(0.05, v.duration);
        const stagger = Math.max(0, v.stagger);
        const span = spanOf(frame);
        drawGlobe(ctx, frame, radiusOf(frame), ({ steps }) => {
          // A shorter orb (fading out mid-change) starts later so both finish together.
          const lead = span - steps * stagger;
          return ({ x, y, z, step }, out) => {
            const d = step + (steps - 2 * step) * fromBottom;
            const t = Math.min(1, Math.max(0, (now - lead - d * stagger) / turn));
            // Push out and settle back on a sine bump: starts and lands at rest, no snap at either end.
            const s = 1 + lift * Math.sin(Math.PI * t) ** 2;
            // Only x and z scale: each ring widens or narrows around the vertical axis and never leaves its height.
            out.x = x * s;
            out.y = y;
            out.z = z * s;
          };
        });
      },
    };
  },
};

interface TideSettings {
  depth: number;
  width: number;
  duration: number;
  gap: number;
  from: "top" | "bottom";
}

/** A narrow wave travels down the orb, pulling a few rows inward as it passes. */
const tideMotion = {
  targets(s: TideSettings) {
    return {
      depth: s.depth,
      width: s.width,
      duration: s.duration,
      gap: s.gap,
      // 0 runs the wave top to bottom, 1 bottom to top; gliding between them turns the tide smoothly.
      from: s.from === "bottom" ? 1 : 0,
    };
  },
  scene(): Scene<unknown, "depth" | "width" | "duration" | "gap" | "from" | GlobeKey, GlobeShape> {
    // One sweep, then a rest for `gap`; advanced by rate so pausing coasts to a stop. The sweep keeps its
    // progress, so a duration change only changes the wave's speed and never jumps it along the orb.
    const loop: MoveLoop = { at: 0, rested: 0 };

    return {
      advance(dt, { v }) {
        runMoveLoop(loop, dt * v.rate, Math.max(0.05, v.duration), Math.max(0, v.gap));
      },
      draw(ctx, frame) {
        const { v } = frame;
        const sink = Math.min(0.9, Math.max(0, v.depth));
        const half = Math.max(0.5, v.width) / 2;
        const fromBottom = v.from;
        // How far the wave has travelled this sweep (0–1), at a constant speed; it holds at 1 through the gap, past the far pole.
        const travel = loop.at;

        drawGlobe(ctx, frame, radiusOf(frame), ({ steps }) => {
          // The wave's middle, in steps; it starts and ends fully off the orb so it enters and leaves softly.
          const mid = -half + travel * (steps + half * 2);
          return ({ x, y, z, step }, out) => {
            const d = step + (steps - 2 * step) * fromBottom;
            // 1 at the middle of the wave, easing to 0 `half` steps either side, so only a few rows move at once.
            const dist = Math.abs(d - mid) / half;
            const w = dist < 1 ? Math.cos((Math.PI / 2) * dist) ** 2 : 0;
            const s = 1 - sink * w;
            // Only x and z scale: each ring narrows toward the vertical axis and never leaves its height.
            out.x = x * s;
            out.y = y;
            out.z = z * s;
            // Pulled-in dots shrink and dim, so the wave reads as passing inside the orb.
            out.size = s;
            out.dim = 1 - (1 - TIDE_SUNK_OPACITY) * w * Math.min(1, sink * 4);
          };
        });
      },
    };
  },
};

interface TwistSettings {
  moves: number;
  duration: number;
  gap: number;
}

/** One cube turn: a third of the orb turning about the vertical axis (a row) or the horizontal one (a column). */
type Turn = { id: number; axis: "row" | "column"; layer: -1 | 0 | 1; sign: 1 | -1 };

/** Where each dot of one orb sits while it is being twisted, in the orb's own turning frame. */
interface TwistState {
  /** The pattern itself; a solved orb sits exactly here. */
  base: Float64Array;
  /** Where each dot sits between turns. */
  pos: Float64Array;
  /** Each dot's turn about the vertical axis: a quarter, snapped so the turn lands it back on the pattern. */
  quarter: Float64Array;
  /** A column's turn over the top: a half turn, or a whole one where a half would land between the dots. */
  flip: number;
  /** Where a layer starts: dots further than this from the middle along the turn's axis are in an outer layer. */
  edge: number;
  index: Map<GlobePoint, number>;
  /** 1 for the dots in the turn under way. */
  turning: Uint8Array;
  /** Scramble turns this orb took, so a solve undoes only those (an orb that morphed in midway took fewer). */
  taken: Set<number>;
}

const GOLDEN = Math.PI * (3 - Math.sqrt(5));

/**
 * How far past a layer's edge a dot must sit to count as in the outer layer. The edge can fall exactly on
 * a ring's dots; without slack, rounding would put one dot of a mirrored pair in the layer and not the other.
 */
const EDGE_SLACK = 1e-7;

/** The nearest whole number of `n`ths of a circle to a quarter turn, at least one. */
function snappedQuarter(n: number) {
  return ((Math.PI * 2) / n) * Math.max(1, Math.round(n / 4));
}

function buildTwist(shape: GlobeShape): TwistState {
  const { points, rows, pattern } = shape;
  const count = points.length;
  const cols = rows * 2;
  // The spiral is symmetric under a half turn about one horizontal axis, which swaps dot i with dot count-1-i.
  // Spinning the orb so that axis is the column axis makes every column flip land the spiral back on itself.
  const frame = pattern === "fibonacci" ? (((count - 1) * GOLDEN) / 2) % Math.PI : 0;
  const sinF = Math.sin(frame);
  const cosF = Math.cos(frame);

  const base = new Float64Array(count * 3);
  const quarter = new Float64Array(count);
  points.forEach(({ x, y, z, row }, i) => {
    base[i * 3] = x * cosF + z * sinF;
    base[i * 3 + 1] = y;
    base[i * 3 + 2] = -x * sinF + z * cosF;
    // No turn about the vertical axis lands the spiral back on itself, so its rows go all the way round.
    if (pattern === "fibonacci") quarter[i] = Math.PI * 2;
    else if (pattern === "grid") quarter[i] = snappedQuarter(cols);
    else {
      // Each ring turns by its own nearest quarter of its dot spacing, so it lands on its own dots. A column
      // flip only ever swaps ring i with ring rows-i, which has as many dots, so this never changes for a dot.
      const r = Math.cos(Math.PI / 2 - (row / rows) * Math.PI);
      quarter[i] = row === 0 || row === rows ? Math.PI / 2 : snappedQuarter(Math.max(1, Math.round(cols * r)));
    }
  });

  // Thirds of the orb, like a 3×3 cube, with the cut halfway between two rows so no ring is ever split.
  const cut = Math.round(rows / 3 - 0.5) + 0.5;
  return {
    base,
    pos: base.slice(),
    quarter,
    // A half turn swaps ring i with ring rows-i; with an odd row count their dots sit half a step apart.
    flip: pattern === "rings" && rows % 2 === 1 ? Math.PI * 2 : Math.PI,
    edge: Math.cos((cut / rows) * Math.PI),
    index: new Map(points.map((p, i) => [p, i])),
    turning: new Uint8Array(count),
    taken: new Set(),
  };
}

/** Rotates dot `i` of `pos` by `angle` for `turn`, into `out`. */
function rotateDot(pos: Float64Array, i: number, turn: Turn, angle: number, out: { x: number; y: number; z: number }) {
  const x = pos[i * 3];
  const y = pos[i * 3 + 1];
  const z = pos[i * 3 + 2];
  const sinA = Math.sin(angle);
  const cosA = Math.cos(angle);
  if (turn.axis === "row") {
    out.x = x * cosA + z * sinA;
    out.y = y;
    out.z = -x * sinA + z * cosA;
  } else {
    out.x = x;
    out.y = y * cosA - z * sinA;
    out.z = y * sinA + z * cosA;
  }
}

/**
 * The orb scrambles and solves itself like a twisty cube. Each turn spins a third of it, a row about the
 * vertical axis or a column over the top; after `moves` turns the same turns play back in reverse.
 */
const twistMotion = {
  targets(s: TwistSettings) {
    return { moves: s.moves, duration: s.duration, gap: s.gap };
  },
  scene(): Scene<unknown, "moves" | "duration" | "gap" | GlobeKey, GlobeShape> {
    type V = Values<"moves" | "duration" | "gap" | GlobeKey>;
    const states = new WeakMap<GlobeShape, TwistState>();
    const stateOf = (shape: GlobeShape) => {
      let state = states.get(shape);
      if (!state) states.set(shape, (state = buildTwist(shape)));
      return state;
    };

    let scramble: Turn[] = [];
    let nextId = 0;
    // The loop runs scramble turns, a hold, the solve (the scramble undone, last turn first), then a rest.
    let stage: "scramble" | "hold" | "solve" | "rest" = "rest";
    let at = 0;
    // Progress through the current turn or pause (0–1), advanced by rate so pausing coasts to a stop.
    let t = 1;

    const current = (): Turn | null => {
      if (stage === "scramble") return scramble[at];
      if (stage === "solve") {
        const turn = scramble[scramble.length - 1 - at];
        return { ...turn, sign: turn.sign === 1 ? -1 : 1 };
      }
      return null;
    };

    const newScramble = (v: V) => {
      const out: Turn[] = [];
      for (let k = 0; k < Math.max(1, Math.round(v.moves)); k++) {
        const prev = out[k - 1];
        let turn: Turn;
        // Never the same layer twice in a row, or the two turns would read as one.
        do {
          turn = {
            id: nextId++,
            axis: Math.random() < 0.5 ? "row" : "column",
            layer: (Math.floor(Math.random() * 3) - 1) as Turn["layer"],
            sign: Math.random() < 0.5 ? 1 : -1,
          };
        } while (prev && prev.axis === turn.axis && prev.layer === turn.layer);
        out.push(turn);
      }
      return out;
    };

    /** Picks the dots in `turn`'s layer, on every orb that took part in it. */
    const begin = (turn: Turn, shapes: GlobeShape[]) => {
      for (const shape of shapes) {
        const state = stateOf(shape);
        const { pos, turning, edge, taken } = state;
        turning.fill(0);
        if (stage === "solve" && !taken.has(turn.id)) continue;
        const offset = turn.axis === "row" ? 1 : 0;
        for (let i = 0; i < turning.length; i++) {
          const c = pos[i * 3 + offset];
          const layer = c > edge + EDGE_SLACK ? 1 : c < -edge - EDGE_SLACK ? -1 : 0;
          if (layer === turn.layer) turning[i] = 1;
        }
      }
    };

    /** Settles every turning dot where the turn left it. */
    const commit = (turn: Turn, shapes: GlobeShape[]) => {
      const out = { x: 0, y: 0, z: 0 };
      for (const shape of shapes) {
        const state = stateOf(shape);
        const { pos, turning, quarter, flip, taken } = state;
        let moved = false;
        for (let i = 0; i < turning.length; i++) {
          if (!turning[i]) continue;
          moved = true;
          rotateDot(pos, i, turn, (turn.axis === "row" ? quarter[i] : flip) * turn.sign, out);
          pos[i * 3] = out.x;
          pos[i * 3 + 1] = out.y;
          pos[i * 3 + 2] = out.z;
        }
        turning.fill(0);
        if (!moved) continue;
        if (stage === "scramble") taken.add(turn.id);
        else taken.delete(turn.id);
        // Solved: snap exactly back onto the pattern so rounding never builds up.
        if (stage === "solve" && taken.size === 0) pos.set(state.base);
      }
    };

    /** Seconds the current stage's step lasts. */
    const lengthOf = (v: V) => (stage === "hold" || stage === "rest" ? Math.max(0, v.gap) : Math.max(0.05, v.duration));

    /** Moves on from a finished step to the next one. */
    const finish = (v: V, shapes: GlobeShape[]) => {
      const turn = current();
      if (turn) commit(turn, shapes);
      t = 0;
      if (stage === "scramble" && ++at >= scramble.length) [stage, at] = ["hold", 0];
      else if (stage === "hold") [stage, at] = ["solve", 0];
      else if (stage === "solve" && ++at >= scramble.length) [stage, at] = ["rest", 0];
      else if (stage === "rest") [stage, at, scramble] = ["scramble", 0, newScramble(v)];
      const next = current();
      if (next) begin(next, shapes);
    };

    let turnNow: Turn | null = null;

    return {
      advance(dt, { v, layers }) {
        const shapes = layers.map((layer) => layer.shape);
        let left = dt * v.rate;
        // Several short steps can pass in one frame (a zero gap takes none at all); cap it so nothing spins.
        for (let guard = 0; guard < 64 && (left > 0 || t >= 1); guard++) {
          if (t >= 1) {
            finish(v, shapes);
            continue;
          }
          const length = lengthOf(v);
          const need = (1 - t) * length;
          if (left < need) {
            t += left / length;
            left = 0;
          } else {
            left -= need;
            t = 1;
          }
        }
        turnNow = current();
      },
      draw(ctx, frame) {
        const turn = turnNow;
        // A cube turn is a part moving across the orb and landing: strong ease-in-out, so it sets off
        // decisively and settles softly onto the pattern.
        const eased = turn ? easeInOut(Math.min(1, t)) : 0;
        // The shared radius, so in DotGlobe switching to twist never resizes the orb.
        drawGlobe(ctx, frame, radiusOf(frame), (shape) => {
          const { pos, turning, quarter, flip, index } = stateOf(shape);
          // Drawn in the turning frame, so columns always flip about the screen's horizontal axis.
          return (point, placed) => {
            const i = index.get(point) ?? 0;
            if (turn && turning[i]) {
              rotateDot(pos, i, turn, (turn.axis === "row" ? quarter[i] : flip) * turn.sign * eased, placed);
            } else {
              placed.x = pos[i * 3];
              placed.y = pos[i * 3 + 1];
              placed.z = pos[i * 3 + 2];
            }
          };
        });
      },
    };
  },
};

/** 1 at a wave's middle `mid`, easing to 0 `half` steps either side: how much of the wave step `d` is in. */
function waveAt(d: number, mid: number, half: number) {
  const dist = Math.abs(d - mid) / half;
  return dist < 1 ? Math.cos((Math.PI / 2) * dist) ** 2 : 0;
}

/** Rows the scan band lights at once: a line or two, like the line being read. */
const SCAN_WIDTH = 1.75;

/** Opacity of the dots the scan isn't on, so the lit band stands out like the line being read. */
const SCAN_REST_OPACITY = 0.5;

/** How much bigger a dot draws at the middle of the scan band. */
const SCAN_SWELL = 0.35;

interface ScanSettings {
  duration: number;
  gap: number;
}

/** A thin band of light reads down the orb at a steady pace, brightening and swelling the dots it is on. */
const scanMotion = {
  targets(s: ScanSettings) {
    return { duration: s.duration, gap: s.gap };
  },
  scene(): Scene<unknown, "duration" | "gap" | GlobeKey, GlobeShape> {
    // One read down the orb, then a rest for `gap`; kept as progress, like the tide, so a duration change only changes the pace.
    const loop: MoveLoop = { at: 0, rested: 0 };

    return {
      advance(dt, { v }) {
        runMoveLoop(loop, dt * v.rate, Math.max(0.05, v.duration), Math.max(0, v.gap));
      },
      draw(ctx, frame) {
        const half = SCAN_WIDTH / 2;
        // Linear: a read moves at a constant pace. It holds at 1 through the gap, past the bottom pole.
        const travel = loop.at;
        drawGlobe(ctx, frame, radiusOf(frame), ({ steps }) => {
          const mid = -half + travel * (steps + half * 2);
          return ({ x, y, z, step }, out) => {
            const w = waveAt(step, mid, half);
            // Nothing moves: the band only lights and swells the dots it passes.
            out.x = x;
            out.y = y;
            out.z = z;
            out.size = 1 + SCAN_SWELL * w;
            out.dim = SCAN_REST_OPACITY + (1 - SCAN_REST_OPACITY) * w;
          };
        });
      },
    };
  },
};

/** Opacity a dot keeps as the upload wave carries it off the top pole, so the wave reads as sent. */
const RISE_SENT_OPACITY = 0.3;

interface RiseSettings {
  lift: number;
  depth: number;
  width: number;
  duration: number;
  gap: number;
  direction: GlobeDirection;
}

/**
 * Up (upload): a wave travels up the orb pushing a few rows outward, fading them as it passes the top pole.
 * Down (download): it travels down pulling them inward, like the tide.
 */
const riseMotion = {
  targets(s: RiseSettings) {
    return {
      lift: s.lift,
      depth: s.depth,
      width: s.width,
      duration: s.duration,
      gap: s.gap,
      // 0 runs the upload, 1 the download; gliding between them turns the wave and swaps push for pull smoothly.
      down: s.direction === "down" ? 1 : 0,
    };
  },
  scene(): Scene<unknown, "lift" | "depth" | "width" | "duration" | "gap" | "down" | GlobeKey, GlobeShape> {
    // One sweep, then a rest for `gap`, kept as progress like the tide.
    const loop: MoveLoop = { at: 0, rested: 0 };

    return {
      advance(dt, { v }) {
        runMoveLoop(loop, dt * v.rate, Math.max(0.05, v.duration), Math.max(0, v.gap));
      },
      draw(ctx, frame) {
        const { v } = frame;
        const push = Math.max(0, v.lift);
        const sink = Math.min(0.9, Math.max(0, v.depth));
        const half = Math.max(0.5, v.width) / 2;
        const down = v.down;
        // Linear: a transfer moves at a constant pace. It holds at 1 through the gap, past the far pole.
        const travel = loop.at;

        drawGlobe(ctx, frame, radiusOf(frame), ({ steps }) => {
          const mid = -half + travel * (steps + half * 2);
          return ({ x, y, z, step }, out) => {
            // Steps from the pole the wave sets off from: the bottom for an upload, the top for a download.
            const d = step + (steps - 2 * step) * (1 - down);
            const w = waveAt(d, mid, half);
            const s = 1 + (push * (1 - down) - sink * down) * w;
            // Only x and z scale: each ring widens or narrows around the vertical axis and never leaves its height.
            out.x = x * s;
            out.y = y;
            out.z = z * s;
            // An upload fades its dots the nearer the top they are carried, so the wave reads as sent off the orb;
            // a download's pulled-in dots shrink and dim like the tide's.
            const sent = (1 - RISE_SENT_OPACITY) * w * (d / steps) ** 2;
            const sunk = (1 - TIDE_SUNK_OPACITY) * w * Math.min(1, sink * 4);
            out.size = 1 - sink * w * down;
            out.dim = 1 - sent * (1 - down) - sunk * down;
          };
        });
      },
    };
  },
};

/** Columns the sweep's trail fades over behind its head, so 3–4 columns are lit at once. */
const SWEEP_TRAIL = 3;

/** Columns ahead of the head a dot starts to light, so a column never switches on in a single frame. */
const SWEEP_LEAD = 0.5;

/** Opacity of the dots the sweep isn't on. */
const SWEEP_REST_OPACITY = 0.45;

/** How much bigger a dot draws at the sweep's head. */
const SWEEP_SWELL = 0.3;

/**
 * How far around the vertical axis a point sits, in turns, in the pattern's own order. Rings and grid take
 * the point's angle, so a grid column shares one value; the spiral reads it off the step, so a line of
 * equal value winds down the arms like the spiral's stripe.
 */
function aroundOf({ pattern, steps, rows }: GlobeShape, { x, z, step }: GlobePoint) {
  if (pattern === "fibonacci") return step / (steps - rows);
  return Math.atan2(z, x) / (Math.PI * 2);
}

interface SweepSettings {
  duration: number;
  direction: GlobeDirection;
}

/** One column lights up and sweeps around the orb like a radar, with a short fading trail. The dots never move. */
const sweepMotion = {
  targets(s: SweepSettings) {
    return {
      duration: s.duration,
      // Sweep velocity sign, as spin's; flipping it slows the head, stops it, and sends it back the other way.
      dir: s.direction === "right" ? -1 : 1,
    };
  },
  scene(): Scene<unknown, "duration" | "dir" | GlobeKey, GlobeShape> {
    // Where the head is, in turns around the orb, advanced by rate so pausing coasts to a stop.
    let head = 0;

    return {
      advance(dt, { v }) {
        // A radar turns at a constant pace with no rest: one turn every `duration`, linear.
        head = (((head - (dt * v.rate * v.dir) / Math.max(0.05, v.duration)) % 1) + 1) % 1;
      },
      draw(ctx, frame) {
        const { v } = frame;
        // How much of the trail sits on each side of the head; mid-flip both show, so the trail never jumps sides.
        const left = Math.min(1, Math.max(0, (1 + v.dir) / 2));
        drawGlobe(ctx, frame, radiusOf(frame), (shape) => {
          const cols = shape.rows * 2;
          /** 1 at the head, fading over the trail behind it; `behind` is in turns, measured the way the head came from. */
          const lit = (behind: number) => {
            const c = (((behind % 1) + 1) % 1) * cols;
            if (c <= SWEEP_TRAIL) return 1 - c / SWEEP_TRAIL;
            return Math.max(0, 1 - (cols - c) / SWEEP_LEAD);
          };
          return (point, out) => {
            const a = aroundOf(shape, point);
            // Turning left the head runs toward smaller angles, so the dots it has passed sit at larger ones.
            const w = lit(a - head) * left + lit(head - a) * (1 - left);
            out.x = point.x;
            out.y = point.y;
            out.z = point.z;
            out.size = 1 + SWEEP_SWELL * w;
            out.dim = SWEEP_REST_OPACITY + (1 - SWEEP_REST_OPACITY) * w;
          };
        });
      },
    };
  },
};

/** Rows each compacting wave pulls in, so the two together keep about 4 rows moving. */
const COMPACT_WIDTH = 2;

/** Share of each loop the waves take to travel from the poles to the equator. */
const COMPACT_SQUEEZE = 0.7;

/** Share of each loop the waist holds, pulled in, once the waves meet. The rest lets it go. */
const COMPACT_HOLD = 0.15;

interface CompactSettings {
  depth: number;
  duration: number;
  gap: number;
}

/** Two waves pull rows inward from the poles and meet at the equator, hold there as a thin waist, then let go. */
const compactMotion = {
  targets(s: CompactSettings) {
    return { depth: s.depth, duration: s.duration, gap: s.gap };
  },
  scene(): Scene<unknown, "depth" | "duration" | "gap" | GlobeKey, GlobeShape> {
    // Squeeze, hold and release as one move, then a rest for `gap`, kept as progress like the tide.
    const loop: MoveLoop = { at: 0, rested: 0 };

    return {
      advance(dt, { v }) {
        runMoveLoop(loop, dt * v.rate, Math.max(0.05, v.duration), Math.max(0, v.gap));
      },
      draw(ctx, frame) {
        const half = COMPACT_WIDTH / 2;
        const at = loop.at;
        // The waves move across the orb and settle where they meet: strong ease-in-out. The release is the
        // waist leaving: ease-out, so it lets go at once and settles softly.
        const squeeze = easeInOut(Math.min(1, at / COMPACT_SQUEEZE));
        const release = easeOut(Math.max(0, (at - COMPACT_SQUEEZE - COMPACT_HOLD) / (1 - COMPACT_SQUEEZE - COMPACT_HOLD)));
        const sink = Math.min(0.9, Math.max(0, frame.v.depth)) * (1 - release);

        drawGlobe(ctx, frame, radiusOf(frame), ({ steps }) => {
          // Each wave's middle, in steps from its own pole; both start just off the orb and stop at the equator.
          const mid = -half + squeeze * (steps / 2 + half);
          return ({ x, y, z, step }, out) => {
            // Steps from the nearer pole, so the two waves mirror each other and overlap into one waist.
            const w = waveAt(Math.min(step, steps - step), mid, half);
            const s = 1 - sink * w;
            // Only x and z scale: each ring narrows toward the vertical axis and never leaves its height.
            out.x = x * s;
            out.y = y;
            out.z = z * s;
            // Pulled-in dots shrink and dim like the tide's, so the waist reads as drawn inside the orb.
            out.size = s;
            out.dim = 1 - (1 - TIDE_SUNK_OPACITY) * w * Math.min(1, sink * 4);
          };
        });
      },
    };
  },
};

/** Rows each swarm wave moves at once: narrow, so several waves still read as separate bands. */
const SWARM_WIDTH = 1.5;

/** Most waves a swarm runs; each one is a call running alongside the others. */
const SWARM_MAX = 4;

interface SwarmSettings {
  waves: number;
  lift: number;
  depth: number;
  duration: number;
}

/**
 * Several narrow waves travel down the orb at once, evenly spaced, like that many tides running side by side.
 * Waves take turns pulling their rows inward and pushing them outward, so neighboring waves read apart.
 */
const swarmMotion = {
  targets(s: SwarmSettings) {
    return { waves: Math.min(SWARM_MAX, Math.max(1, Math.round(s.waves))), lift: s.lift, depth: s.depth, duration: s.duration };
  },
  scene(): Scene<unknown, "waves" | "lift" | "depth" | "duration" | GlobeKey, GlobeShape> {
    // How far the first wave has travelled (0–1), at a constant pace with no rest: the waves behind it keep the orb busy.
    let travel = 0;

    return {
      advance(dt, { v }) {
        travel = (travel + (dt * v.rate) / Math.max(0.05, v.duration)) % 1;
      },
      draw(ctx, frame) {
        const { v } = frame;
        const push = Math.max(0, v.lift);
        const sink = Math.min(0.9, Math.max(0, v.depth));
        const half = SWARM_WIDTH / 2;
        // Glides, so a change of count slides the waves to their new spacing and fades the extra one in or out.
        const count = Math.min(SWARM_MAX, Math.max(1, v.waves));

        drawGlobe(ctx, frame, radiusOf(frame), ({ steps }) => {
          const span = steps + half * 2;
          const mids: number[] = [];
          for (let k = 0; k < Math.ceil(count); k++) mids.push(-half + ((travel + k / count) % 1) * span);
          return ({ x, y, z, step }, out) => {
            let s = 1;
            let sunk = 0;
            for (let k = 0; k < mids.length; k++) {
              const w = waveAt(step, mids[k], half) * Math.min(1, count - k);
              if (k % 2) s += push * w;
              else {
                s -= sink * w;
                sunk += w;
              }
            }
            // Only x and z scale: each ring widens or narrows around the vertical axis and never leaves its height.
            out.x = x * s;
            out.y = y;
            out.z = z * s;
            // Pulled-in dots shrink and dim like the tide's.
            out.size = Math.min(1, s);
            out.dim = 1 - (1 - TIDE_SUNK_OPACITY) * Math.min(1, sunk) * Math.min(1, sink * 4);
          };
        });
      },
    };
  },
};

/** Glide key for how much of animation `A` is on screen: 1 while it is the active one, 0 when it is gone. */
type MixKey<A extends string> = `mix_${A}`;

/** One mix target per animation: 1 for the active one, 0 for the rest. They glide, so a switch cross-fades. */
function mixTargets<A extends string>(names: readonly A[], active: A) {
  const out = {} as Record<MixKey<A>, number>;
  for (const name of names) out[`mix_${name}`] = name === active ? 1 : 0;
  return out;
}

/** `defaults` with every prop that was actually passed laid over it; an `undefined` prop keeps the default. */
function withDefaults<T extends object>(defaults: T, props: { [P in keyof T]?: T[P] }): T {
  const out = { ...defaults };
  for (const key in props) {
    const value = props[key];
    if (value !== undefined) out[key] = value as T[typeof key];
  }
  return out;
}

/**
 * Runs several scenes as one, each faded by its `mix_<name>` glide. Switching the active animation fades
 * the old scene out while the new one fades in. A scene that is fully faded out holds its clock still.
 */
function mixScenes<S, K extends string, L, A extends string>(
  scenes: Record<A, () => Scene<S, K, L>>,
): Scene<S, K | MixKey<A> | "alpha", L> {
  const live = (Object.keys(scenes) as A[]).map((name) => ({ key: `mix_${name}` as MixKey<A>, scene: scenes[name]() }));
  return {
    advance(dt, frame) {
      for (const { key, scene } of live) if (frame.v[key] > 0) scene.advance?.(dt, frame);
    },
    draw(ctx, frame) {
      const { v } = frame;
      const alpha = v.alpha;
      for (const { key, scene } of live) {
        const weight = v[key];
        if (weight <= 0) continue;
        // Scenes paint at `v.alpha`, so scaling it fades the whole scene.
        v.alpha = alpha * weight;
        scene.draw(ctx, frame);
      }
      v.alpha = alpha;
    },
  };
}
